from fastapi import File, UploadFile


@router.post('/invoices/import')
async def import_invoices(file: UploadFile = File(...)) -> dict:
    total = 0
    while chunk := await file.read(1 << 20):
        total += handle_chunk(chunk)
    return {'rows': total}
```

`UploadFile` spools to disk past a threshold, so a large upload does not sit in RAM.

